    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 10px;
  }

  .page-title {
    font-family: var(--font-display);
    font-size: clamp(22px, 3vw, 34px);
    font-weight: 700;
    line-height: 1.2;
    color: #f0e8d6;
    letter-spacing: -0.01em;
  }

  .page-subtitle {
    margin-top: 8px;
    font-size: 14px;
    color: var(--text-dim);
    max-width: 560px;
    line-height: 1.5;
  }

  .page-meta {
    text-align: right;
    font-family: var(--font-mono);
    font-size: 11px;
    color: var(--text-muted);
    line-height: 1.7;
  }

  /* ── KPI Strip ───────────────────────────────────────────────── */
  .kpi-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 32px;
  }

  .kpi-card {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 18px 20px;
    position: relative;
    overflow: hidden;
  }

  .kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
  }
  .kpi-card.gold::before { background: var(--gold); }
  .kpi-card.crimson::before { background: var(--crimson); }
  .kpi-card.teal::before { background: var(--teal); }
  .kpi-card.slate::before { background: var(--slate); }

  .kpi-label {
    font-family: var(--font-mono);
    font-size: 10px;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--text-muted);
    margin-bottom: 6px;
  }

  .kpi-value {
    font-family: var(--font-display);
    font-size: 26px;
    font-weight: 700;
    line-height: 1;
    margin-bottom: 4px;
  }
  .kpi-card.gold .kpi-value { color: var(--gold-light); }
  .kpi-card.crimson .kpi-value { color: #e07382; }
  .kpi-card.teal .kpi-value { color: #4ecdc4; }
  .kpi-card.slate .kpi-value { color: #aabfd3; }

  .kpi-delta {
    font-size: 12px;
    color: var(--text-dim);
  }

  /* ── Chart grid ──────────────────────────────────────────────── */
  .charts-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    grid-template-rows: auto auto;
    gap: 20px;
  }

  .chart-panel {
    background: var(--surface);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 24px 28px 20px;
    min-width: 0;
  }

  .chart-panel.wide {
    grid-column: 1 / -1;
  }

  .panel-label {
    font-family: var(--font-mono);
    font-size: 10px;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 4px;
  }

  .panel-title {
    font-family: var(--font-display);
    font-size: 17px;
    font-weight: 600;
    color: #eee4d0;
    margin-bottom: 3px;
  }

  .panel-desc {
    font-size: 12px;
    color: var(--text-muted);
    margin-bottom: 18px;
    line-height: 1.4;
  }

  .chart-wrap {
    position: relative;
  }

  /* ── Policy events legend ────────────────────────────────────── */
  .events-legend {
    margin-top: 18px;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(230px, 1fr));
    gap: 6px 16px;
  }

  .event-item {
    display: flex;
    align-items: flex-start;
    gap: 8px;
    font-size: 11px;
    color: var(--text-dim);
    line-height: 1.4;
  }

  .event-dot {
    flex-shrink: 0;
    width: 8px;
    height: 8px;
    border-radius: 50%;
    margin-top: 3px;
  }
  .event-dot.tariff { background: var(--crimson); }
  .event-dot.deal   { background: var(--teal); }
  .event-dot.review { background: var(--gold); }
  .event-dot.investigation { background: var(--slate); }

  .event-date {
    font-family: var(--font-mono);
    font-size: 10px;
    color: var(--text-muted);
    flex-shrink: 0;
    min-width: 50px;
  }

  /* ── Legend strips ───────────────────────────────────────────── */
  .legend-row {
    display: flex;
    flex-wrap: wrap;
    gap: 14px;
    margin-bottom: 14px;
  }
  .legend-item {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 12px;
    color: var(--text-dim);
  }
  .legend-swatch {
    width: 24px;
    height: 3px;
    border-radius: 2px;
  }
  .legend-swatch.dashed {
    background: repeating-linear-gradient(to right, currentColor 0 4px, transparent 4px 8px);
  }

  /* ── Footer ──────────────────────────────────────────────────── */
  .page-footer {
    margin-top: 36px;
    padding-top: 18px;
    border-top: 1px solid var(--border);
    display: flex;
    justify-content: space-between;
    align-items: center;
    font-family: var(--font-mono);
    font-size: 10px;
    color: var(--text-muted);
    flex-wrap: wrap;
    gap: 8px;
  }

  .cat-pill {
    display: inline-block;
    padding: 1px 7px;
    border-radius: 4px;
    font-size: 10px;
    font-family: var(--font-mono);
    margin-left: 4px;
    vertical-align: middle;
  }
  .cat-tariff   { background: var(--crimson-dim); color: #e07382; border: 1px solid rgba(184,58,75,0.3); }
  .cat-deal     { background: var(--teal-dim);    color: #4ecdc4; border: 1px solid rgba(42,157,143,0.3); }
  .cat-review   { background: var(--gold-dim);    color: var(--gold-light); border: 1px solid rgba(201,153,58,0.3); }
  .cat-inv      { background: rgba(126,147,173,0.1); color: #aabfd3; border: 1px solid rgba(126,147,173,0.3); }

  @media (max-width: 700px) {
    .kpi-strip { grid-template-columns: 1fr 1fr; }
    .charts-grid { grid-template-columns: 1fr; }
    .chart-panel.wide { grid-column: auto; }
    .page-header { grid-template-columns: 1fr; }
    .page-meta { text-align: left; }
  }
</style>
</head>
<body>
<div class="page-wrapper">

  <!-- Header -->
  <header class="page-header">
    <div>
      <div class="page-eyebrow">Geopolitical Economics · Trade Policy Analysis</div>
      <h1 class="page-title">US–China Trade War<br>Tariffs, Volumes & Supply Chain Shifts</h1>
      <p class="page-subtitle">Bilateral tariff escalation, trade flow trajectories, and emerging market-share gains by Vietnam and India, 2016–2024.</p>
    </div>
    <div class="page-meta">
      Period: 2016–2024<br>
      Sources: USTR, US Census Bureau,<br>
      Peterson Institute, PIIE<br>
      Units: % and USD Billion
    </div>
  </header>

  <!-- KPI Strip -->
  <div class="kpi-strip">
    <div class="kpi-card gold">
      <div class="kpi-label">US Tariff Peak (2024-H1)</div>
      <div class="kpi-value">25.4%</div>
      <div class="kpi-delta">vs. 3.1% in 2017 · +720 bps</div>
    </div>
    <div class="kpi-card crimson">
      <div class="kpi-label">China Tariff Peak (2024-H1)</div>
      <div class="kpi-value">23.1%</div>
      <div class="kpi-delta">vs. 8.0% in 2017 · +190 bps</div>
    </div>
    <div class="kpi-card teal">
      <div class="kpi-label">China Import Share Drop</div>
      <div class="kpi-value">−8.8pp</div>
      <div class="kpi-delta">21.6% (2017) → 12.8% (2024)</div>
    </div>
    <div class="kpi-card slate">
      <div class="kpi-label">Bilateral Trade 2024 est.</div>
      <div class="kpi-value">$540B</div>
      <div class="kpi-delta">Peak $691B (2022) · −22%</div>
    </div>
  </div>

  <!-- Charts Grid -->
  <div class="charts-grid">

    <!-- Panel 1: Tariff escalation timeline -->
    <div class="chart-panel wide">
      <div class="panel-label">Chart 1 · Tariff Escalation Timeline</div>
      <div class="panel-title">Stepwise Tariff Escalation: US on China & China on US</div>
      <div class="panel-desc">Average effective tariff rates (trade-weighted) by half-year period, with key policy events annotated. Rates held largely steady 2020–2023 following the Phase One deal; Biden's 2024 EV/semiconductor tariffs triggered a new US rate spike.</div>
      <div class="legend-row">
        <div class="legend-item"><span class="legend-swatch" style="background:#e8bb6a"></span> US tariff on Chinese goods</div>
        <div class="legend-item"><span class="legend-swatch" style="background:#e07382"></span> China tariff on US goods</div>
        <div class="legend-item"><span style="width:10px;height:10px;background:rgba(184,58,75,0.5);border-radius:2px;display:inline-block"></span> &nbsp;Tariff event</div>
        <div class="legend-item"><span style="width:10px;height:10px;background:rgba(42,157,143,0.5);border-radius:2px;display:inline-block"></span> &nbsp;Deal event</div>
        <div class="legend-item"><span style="width:10px;height:10px;background:rgba(201,153,58,0.5);border-radius:2px;display:inline-block"></span> &nbsp;Review event</div>
      </div>
      <div class="chart-wrap">
        <canvas id="tariffChart" height="110"></canvas>
      </div>
    </div>

    <!-- Panel 2: Bilateral trade volume -->
    <div class="chart-panel">
      <div class="panel-label">Chart 2 · Bilateral Trade Volume</div>
      <div class="panel-title">US–China Total Trade (Exports + Imports)</div>
      <div class="panel-desc">Annual bilateral trade in USD billions. Sharp contraction in 2019 as tariffs bit; partial 2021–22 recovery reversed by 2023–24 decoupling pressures.</div>
      <div class="legend-row">
        <div class="legend-item"><span class="legend-swatch" style="background:#e8bb6a"></span> US exports to China</div>
        <div class="legend-item"><span class="legend-swatch" style="background:#4d9de0"></span> US imports from China</div>
      </div>
      <div class="chart-wrap">
        <canvas id="tradeVolumeChart" height="180"></canvas>
      </div>
    </div>

    <!-- Panel 3: Supply chain share -->
    <div class="chart-panel">
      <div class="panel-label">Chart 3 · Supply Chain Diversion</div>
      <div class="panel-title">Share of US Goods Imports by Source</div>
      <div class="panel-desc">China's share declining from 21.6% (2017) to 12.8% (2024) as Vietnam and India steadily absorb displaced manufacturing. Post-2018 acceleration is clearly visible.</div>
      <div class="legend-row">
        <div class="legend-item"><span class="legend-swatch" style="background:#e07382"></span> China</div>
        <div class="legend-item"><span class="legend-swatch" style="background:#4ecdc4"></span> Vietnam</div>
        <div class="legend-item"><span class="legend-swatch" style="background:#e8bb6a"></span> India</div>
      </div>
      <div class="chart-wrap">
        <canvas id="supplyChainChart" height="180"></canvas>
      </div>
    </div>

  </div>

  <!-- Policy Events -->
  <div class="chart-panel" style="margin-top:20px;">
    <div class="panel-label">Policy Milestones</div>
    <div class="panel-title">Key Trade Policy Events, 2017–2024</div>
    <div class="panel-desc">Annotated milestones categorized by type: <span class="cat-pill cat-tariff">tariff</span><span class="cat-pill cat-deal">deal</span><span class="cat-pill cat-review">review</span><span class="cat-pill cat-inv">investigation</span></div>
    <div class="events-legend" id="eventsLegend"></div>
  </div>

  <footer class="page-footer">
    <span>Data: USTR · US Census Bureau · Peterson Institute for International Economics (PIIE) · 2024 figures are partial-year estimates</span>
    <span>US–China Trade War Analysis · 2016–2024</span>
  </footer>

</div>

<script src="/app/libs/chart.js"></script>
<script>
  /* ─── Shared helpers ─────────────────────────────────────────── */
  const textColor  = '#7e93ad';
  const gridColor  = 'rgba(255,255,255,0.05)';
  const font       = "'Source Sans 3', system-ui, sans-serif";
  const mono       = "'Roboto Mono', Consolas, monospace";

  Chart.defaults.color = textColor;
  Chart.defaults.font.family = font;
  Chart.defaults.font.size = 11;

  /* ─── Tariff data ────────────────────────────────────────────── */
  const tariffPeriods = [
    '2017-H1','2017-H2',
    '2018-H1','2018-H2',
    '2019-H1','2019-H2',
    '2020-H1','2020-H2',
    '2021-H1','2021-H2',
    '2022-H1','2022-H2',
    '2023-H1','2023-H2',
    '2024-H1'
  ];
  const usTariff  = [3.1,3.1, 3.8,12.0, 18.3,21.0, 19.3,19.3, 19.3,19.3, 19.3,19.3, 19.3,19.3, 25.4];
  const cnTariff  = [8.0,8.0, 8.0,16.5, 20.7,21.8, 20.9,20.9, 20.9,20.9, 21.1,21.1, 21.2,21.2, 23.1];

  /* Policy events mapped to period index (0-based) */
  const policyEvents = [
    { idx: 1,  label: 'Sec.301 Initiated',             cat: 'investigation' },
    { idx: 2,  label: 'Sec.301 Memo ($50B announced)', cat: 'tariff' },
    { idx: 3,  label: 'Lists 1–3 take effect',         cat: 'tariff' },
    { idx: 4,  label: 'List 3 raised to 25%',          cat: 'tariff' },
    { idx: 5,  label: 'List 4A (15% on $112B)',        cat: 'tariff' },
    { idx: 6,  label: 'Phase One deal signed',         cat: 'deal' },
    { idx: 9,  label: 'USTR Tai tariff review',        cat: 'review' },
    { idx: 10, label: 'Biden considers exclusions',    cat: 'review' },
    { idx: 14, label: 'Biden raises EV/semi tariffs',  cat: 'tariff' },
  ];

  const catColors = {
    tariff:      'rgba(184,58,75,0.18)',
    deal:        'rgba(42,157,143,0.18)',
    review:      'rgba(201,153,58,0.18)',
    investigation:'rgba(126,147,173,0.18)',
  };
  const catBorder = {
    tariff:      'rgba(184,58,75,0.55)',
    deal:        'rgba(42,157,143,0.55)',
    review:      'rgba(201,153,58,0.55)',
    investigation:'rgba(126,147,173,0.55)',
  };

  /* Build annotation plugin config */
  const annotationBoxes = {};
  policyEvents.forEach((ev, i) => {
    annotationBoxes[`box${i}`] = {
      type: 'box',
      xMin: ev.idx - 0.4,
      xMax: ev.idx + 0.4,
      backgroundColor: catColors[ev.cat],
      borderColor: catBorder[ev.cat],
      borderWidth: 1,
    };
  });

  /* ─── Chart 1: Tariff escalation ─────────────────────────────── */
  new Chart(document.getElementById('tariffChart'), {
    type: 'line',
    data: {
      labels: tariffPeriods,
      datasets: [
        {
          label: 'US tariff on China (%)',
          data: usTariff,
          borderColor: '#e8bb6a',
          backgroundColor: 'rgba(232,187,106,0.08)',
          borderWidth: 2.5,
          pointRadius: 3,
          pointBackgroundColor: '#e8bb6a',
          tension: 0,
          fill: true,
          stepped: 'before',
        },
        {
          label: 'China tariff on US (%)',
          data: cnTariff,
          borderColor: '#e07382',
          backgroundColor: 'rgba(224,115,130,0.06)',
          borderWidth: 2.5,
          pointRadius: 3,
          pointBackgroundColor: '#e07382',
          tension: 0,
          fill: true,
          stepped: 'before',
        }
      ]
    },
    options: {
      responsive: true,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: '#131f2e',
          borderColor: 'rgba(255,255,255,0.12)',
          borderWidth: 1,
          titleColor: '#dde4ef',
          bodyColor: '#7e93ad',
          padding: 10,
          callbacks: {
            label: ctx => ` ${ctx.dataset.label}: ${ctx.parsed.y}%`
          }
        },
      },
      scales: {
        x: {
          ticks: {
            color: textColor,
            font: { family: mono, size: 10 },
            maxRotation: 45,
            autoSkip: false,
          },
          grid: { color: gridColor },
        },
        y: {
          min: 0, max: 30,
          title: { display: true, text: 'Avg. Effective Tariff Rate (%)', color: textColor, font: { family: font, size: 11 } },
          ticks: { color: textColor, callback: v => v + '%' },
          grid: { color: gridColor },
        }
      }
    }
  });

  /* ─── Chart 2: Bilateral trade volume ───────────────────────── */
  const tradeYears = [2016,2017,2018,2019,2020,2021,2022,2023,2024];
  const usExports  = [115.6,129.9,120.3,106.4,124.5,151.1,153.8,147.8,138.2];
  const usImports  = [462.6,505.5,539.5,452.2,435.4,506.4,536.8,427.2,401.5];

  new Chart(document.getElementById('tradeVolumeChart'), {
    type: 'bar',
    data: {
      labels: tradeYears,
      datasets: [
        {
          label: 'US exports to China ($B)',
          data: usExports,
          backgroundColor: 'rgba(232,187,106,0.55)',
          borderColor: '#e8bb6a',
          borderWidth: 1,
          borderRadius: 3,
          stack: 'trade',
        },
        {
          label: 'US imports from China ($B)',
          data: usImports,
          backgroundColor: 'rgba(77,157,224,0.5)',
          borderColor: '#4d9de0',
          borderWidth: 1,
          borderRadius: 3,
          stack: 'trade',
        }
      ]
    },
    options: {
      responsive: true,
      interaction: { mode: 'index' },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: '#131f2e',
          borderColor: 'rgba(255,255,255,0.12)',
          borderWidth: 1,
          titleColor: '#dde4ef',
          bodyColor: '#7e93ad',
          padding: 10,
          callbacks: {
            footer: items => {
              const total = items.reduce((s, i) => s + i.parsed.y, 0);
              return `Total: $${total.toFixed(1)}B`;
            }
          }
        },
      },
      scales: {
        x: {
          stacked: true,
          ticks: { color: textColor, font: { family: mono, size: 10 } },
          grid: { color: gridColor },
        },
        y: {
          stacked: true,
          title: { display: true, text: 'USD Billion', color: textColor, font: { family: font, size: 11 } },
          ticks: { color: textColor, callback: v => '$' + v },
          grid: { color: gridColor },
        }
      }
    }
  });

  /* ─── Chart 3: Supply chain share ───────────────────────────── */
  const scYears   = [2016,2017,2018,2019,2020,2021,2022,2023,2024];
  const chinaShare   = [21.4,21.6,21.2,18.1,18.6,17.9,16.5,13.9,12.8];
  const vietnamShare = [2.1,2.2,2.6,2.9,3.4,3.7,3.9,4.5,4.9];
  const indiaShare   = [2.1,2.2,2.3,2.4,2.3,2.7,2.8,3.1,3.4];

  new Chart(document.getElementById('supplyChainChart'), {
    type: 'line',
    data: {
      labels: scYears,
      datasets: [
        {
          label: 'China (%)',
          data: chinaShare,
          borderColor: '#e07382',
          backgroundColor: 'rgba(224,115,130,0.1)',
          borderWidth: 2.5,
          pointRadius: 4,
          pointBackgroundColor: '#e07382',
          tension: 0.3,
          fill: false,
        },
        {
          label: 'Vietnam (%)',
          data: vietnamShare,
          borderColor: '#4ecdc4',
          backgroundColor: 'rgba(78,205,196,0.08)',
          borderWidth: 2,
          pointRadius: 4,
          pointBackgroundColor: '#4ecdc4',
          tension: 0.3,
          fill: false,
        },
        {
          label: 'India (%)',
          data: indiaShare,
          borderColor: '#e8bb6a',
          backgroundColor: 'rgba(232,187,106,0.08)',
          borderWidth: 2,
          pointRadius: 4,
          pointBackgroundColor: '#e8bb6a',
          borderDash: [],
          tension: 0.3,
          fill: false,
        }
      ]
    },
    options: {
      responsive: true,
      interaction: { mode: 'index', intersect: false },
      plugins: {
        legend: { display: false },
        tooltip: {
          backgroundColor: '#131f2e',
          borderColor: 'rgba(255,255,255,0.12)',
          borderWidth: 1,
          titleColor: '#dde4ef',
          bodyColor: '#7e93ad',
          padding: 10,
          callbacks: {
            label: ctx => ` ${ctx.dataset.label}: ${ctx.parsed.y}%`
          }
        },
        annotation: {
          annotations: {
            warningLine: {
              type: 'line',
              xMin: 2, xMax: 2,
              borderColor: 'rgba(232,187,106,0.3)',
              borderWidth: 1,
              borderDash: [4,3],
              label: {
                display: true,
                content: '2018 tariffs',
                color: 'rgba(232,187,106,0.6)',
                font: { family: mono, size: 10 },
                position: 'start',
                yAdjust: -8,
              }
            }
          }
        }
      },
      scales: {
        x: {
          ticks: { color: textColor, font: { family: mono, size: 10 } },
          grid: { color: gridColor },
        },
        y: {
          title: { display: true, text: '% of US Goods Imports', color: textColor, font: { family: font, size: 11 } },
          ticks: { color: textColor, callback: v => v + '%' },
          grid: { color: gridColor },
          min: 0,
        }
      }
    }
  });

  /* ─── Policy events list ────────────────────────────────────── */
  const fullEvents = [
    { date: '2017-08', event: 'Section 301 Investigation Initiated',              cat: 'investigation' },
    { date: '2018-03', event: 'Trump signs Section 301 Memo ($50B announced)',    cat: 'tariff' },
    { date: '2018-07', event: 'List 1: 25% tariff on $34B Chinese goods',        cat: 'tariff' },
    { date: '2018-08', event: 'List 2: 25% tariff on $16B Chinese goods',        cat: 'tariff' },
    { date: '2018-09', event: 'List 3: 10% tariff on $200B Chinese goods',       cat: 'tariff' },
    { date: '2019-05', event: 'List 3 raised to 25% on $200B Chinese goods',     cat: 'tariff' },
    { date: '2019-09', event: 'List 4A: 15% tariff on $112B Chinese goods',      cat: 'tariff' },
    { date: '2020-01', event: 'Phase One Trade Deal signed',                      cat: 'deal' },
    { date: '2020-02', event: 'Phase One reductions — List 4A cut to 7.5%',      cat: 'deal' },
    { date: '2021-10', event: 'USTR Tai announces tariff review framework',       cat: 'review' },
    { date: '2022-06', event: 'Biden considers selective tariff exclusions',      cat: 'review' },
    { date: '2024-05', event: 'Biden raises tariffs: EVs 100%, semis 50%, solar', cat: 'tariff' },
  ];

  const catLabel = { tariff:'tariff', deal:'deal', review:'review', investigation:'investigation' };
  const catClass = { tariff:'cat-tariff', deal:'cat-deal', review:'cat-review', investigation:'cat-inv' };
